function dayNumber(value){
 if(typeof value!=='string'||!value)return null;
 if(/^\d{4}-\d{2}-\d{2}$/.test(value)){const [y,m,d]=value.split('-').map(Number),date=new Date(Date.UTC(y,m-1,d));return date.getUTCFullYear()===y&&date.getUTCMonth()===m-1&&date.getUTCDate()===d?date.getTime()/86400000:null}
 const date=new Date(value);if(!Number.isFinite(date.getTime()))return null;
 const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(date),part=k=>+parts.find(p=>p.type===k).value;
 return Date.UTC(part('year'),part('month')-1,part('day'))/86400000;
}
function companionDays(registeredAt,asOf=ACCOUNT_AS_OF){const start=dayNumber(registeredAt),end=dayNumber(asOf);return start===null||end===null||end<start?null:end-start+1}
