function wrapText(ctx,text,x,y,width,lineHeight){let line='';for(const ch of text){if(ctx.measureText(line+ch).width>width&&line){ctx.fillText(line,x,y);line=ch;y+=lineHeight}else line+=ch}if(line)ctx.fillText(line,x,y);return y+lineHeight}
