let afterwordState={dataKey:'',round:0,source:'demo',items:[],attempted:false},afterwordRequest=0,afterwordBusy=false,afterwordError='';
const AFTERWORD_AI_BRIEF='为彩云小译2026年度报告自动匹配3个不同的年度标签，主题「为热爱，跨越语言 / For fandom, beyond language」，面向同人文字与漫画读者。每个标签4至10个汉字，三个标签互补：翻译足迹、留存或表达方式、与故事靠近的方式。根据汇总数据选择实际有依据的三个维度，不提供候选、不要求用户选择。用简短称号或关键词，不含数字、逗号或句末标点。不得推测作品、CP、身份、阅读时段、排名或热爱程度，不从翻译量推断作品类别或阅读完成度。未知不能当零，收藏和自建数据是存量，不能称为本年新增。没有使用记录时用温和的待启程标签。只返回3个非空纯文本标签，不含HTML、解释或留白。';
const matchedTagCache=new Map();
navNames[6]='年度标签';chapters[6]=['年度标签','YOUR ANNUAL TAGS'];introCopy[6]=['为你的热爱，','留下三个印记','让年度足迹<br>成为只属于你的标签卡'];

function getReportStats(){return baseV19GetReportStats().slice(0,9)}
function cardStats(){const all=getReportStats(),indexes=known(data.words)&&data.words>0?[1,known(data.images)&&data.images>0?3:2]:known(data.images)&&data.images>0?[3,7]:[0,2];return {primary:indexes.map(i=>all[i]),secondary:all.filter((s,i)=>!indexes.includes(i))}}

function afterwordDataPayload(){
 const pick=keys=>Object.fromEntries(keys.map(k=>[k,known(data[k])?data[k]:null]));
 return {year:2026,theme:{zh:'为热爱，跨越语言',en:'For fandom, beyond language'},translation2026:pick(['words','pages','images']),savedSnapshot:pick(['favs','webClips']),customizationSnapshot:pick(['libraries','terms','prompts']),usedModelCount2026:getUsedModels()?.length??null};
}
function afterwordDataKey(){return JSON.stringify(afterwordDataPayload())}
function localAfterwordCandidates(){
 const positive=k=>known(data[k])&&data[k]>0,text=positive('words')||positive('pages'),pictures=positive('images');
 const choose=(items,k)=>items[(positive(k)?Math.floor(Math.log10(data[k]+1)):0)%items.length];
 if(!['words','pages','images'].every(k=>known(data[k]))&&!text&&!pictures)return ['故事待续的人','微光仍在路上','下一页的可能'];
 if(!text&&!pictures)return ['故事待启程','下一页的旅人','热爱自由抵达'];
 const primary=text&&pictures?choose(['文字与漫画同行','文字画格漫游者','故事双线探索者'],'pages'):text?choose(['字句漫游者','文字世界探索者','翻页拾光者'],'pages'):choose(['画格漫游者','漫画对白探索者','画面拾光者'],'images');
 const hasSaved=positive('favs')||positive('webClips'),hasCustom=['libraries','terms','prompts'].some(positive),hasPartners=(getUsedModels()?.length||0)>0;
 const saved=choose(['故事留存者','重逢路标收藏者','心动篇页留存者'],'favs');
 const custom=choose(['表达定义者','专属译法搭建者','语气雕琢者'],'terms');
 const partner=['翻译搭档同行者','故事桥梁搭建者','小译同行旅人'][(getUsedModels()?.length||0)%3];
 const secondary=hasSaved?saved:hasCustom?custom:hasPartners?partner:'故事远方来客';
 const third=hasCustom&&secondary!==custom?custom:hasPartners&&secondary!==partner?partner:'为热爱翻页';
 return [primary,secondary,third];
}
function validAfterwordItems(items){return Array.isArray(items)&&items.length===3&&new Set(items).size===3&&items.every(q=>typeof q==='string'&&q===q.trim()&&Array.from(q).length>=4&&Array.from(q).length<=12&&!/[<>，,。！？!?\d\r\n\u0000-\u001f]/.test(q))}
function rememberMatchedTags(){if(!afterwordState.dataKey)return;matchedTagCache.set(afterwordState.dataKey,{...afterwordState,items:[...afterwordState.items]});while(matchedTagCache.size>24)matchedTagCache.delete(matchedTagCache.keys().next().value)}
