  const response=await Promise.race([Promise.resolve().then(()=>host.generateAnnualTags({...afterwordDataPayload(),count:3,instruction:AFTERWORD_AI_BRIEF})),new Promise((_,reject)=>{timeout=setTimeout(()=>reject(new Error('Tag matching timed out')),15000)})]);
  if(!validAfterwordItems(response?.tags))throw new Error('AI must return three annual tags');
