function cardAppearance(){
 const text=known(data.words)&&data.words>0||known(data.pages)&&data.pages>0,images=known(data.images)&&data.images>0;
 const index=text&&images?1:images?2:text?0:!['words','pages','images'].every(k=>known(data[k]))?4:3;
 return AFTERWORD_STYLES[index];
}
function cardMotif(style){return baseV19CardMotif(style).replace('opacity=".15"','opacity=".06"')}
function afterwordArtworkSvg(kind='report'){
 const tags=getAnnualTags(),s=cardAppearance(),portrait=kind==='app-preview'||kind==='preview',height=portrait?720:300;
 const x=portrait?620:748,y=portrait?500:165,w=portrait?236:150,h=portrait?193:123;
 const scene=baseScenePortrait(s.pose).replace('class="scene-mark','class="card-art-scene').replace('<svg ','<svg x="'+x+'" y="'+y+'" width="'+w+'" height="'+h+'" ');
 const font=portrait?48:32,lineHeight=portrait?62:40,top=portrait?164:24,cellHeight=portrait?330:152,cellWidth=portrait?248:264,left=portrait?48:32,step=portrait?284:292;
 const stamps=tags.map((tag,i)=>{
  const chars=Array.from(tag),lines=[],lineCount=Math.ceil(chars.length/4),lineSize=Math.ceil(chars.length/lineCount);for(let at=0;at<chars.length;at+=lineSize)lines.push(chars.slice(at,at+lineSize).join(''));
  const cx=left+i*step+cellWidth/2,startY=top+cellHeight/2-(lines.length-1)*lineHeight/2+font*.35;
  return '<g class="annual-tag-stamp annual-tag-peer" data-tag="'+escapeHtml(tag)+'"><rect x="'+(left+i*step)+'" y="'+top+'" width="'+cellWidth+'" height="'+cellHeight+'" rx="12" fill="'+s.bg+'" fill-opacity=".48" stroke="'+s.gold+'" stroke-opacity=".35"/><text class="annual-tag-text" x="'+cx+'" y="'+startY+'" text-anchor="middle" fill="'+s.ink+'" font-family="Songti SC,STSong,serif" font-size="'+font+'" font-weight="500">'+lines.map((line,j)=>'<tspan x="'+cx+'" y="'+(startY+j*lineHeight)+'">'+escapeHtml(line)+'</tspan>').join('')+'</text></g>';
 }).join('');
 const pattern='<defs><pattern id="tag-pattern-'+kind+'" width="256" height="256" patternUnits="userSpaceOnUse">'+cardMotif(s)+'</pattern></defs>';
 return '<svg xmlns="http://www.w3.org/2000/svg" width="912" height="'+height+'" viewBox="0 0 912 '+height+'" preserveAspectRatio="xMidYMid meet" aria-hidden="true">'+pattern+'<rect x=".5" y=".5" width="911" height="'+(height-1)+'" rx="8" fill="'+s.panel+'" stroke="'+s.gold+'" stroke-opacity=".35"/><rect x="10" y="10" width="892" height="'+(height-20)+'" rx="5" fill="url(#tag-pattern-'+kind+')" stroke="'+s.gold+'" stroke-opacity=".16"/>'+stamps+scene+'</svg>';
}

function ensureCardArtwork(){
 const s=cardAppearance(),stamp=JSON.stringify([s.id,getSummary(),'three-peer-tags-v2']);
 if(cardArtworkCache.get(s.id)?.stamp===stamp)return Promise.resolve(cardArtworkCache.get(s.id));
 if(cardArtworkPromises.get(s.id)?.stamp===stamp)return cardArtworkPromises.get(s.id);
 const load=svg=>new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('Card artwork could not load'));img.src=svgData(svg)});
 const task=Promise.all([load(cardPatternSvg(s)),load(afterwordArtworkSvg('export'))]).then(([pattern,panel])=>{if(JSON.stringify([cardAppearance().id,getSummary(),'three-peer-tags-v2'])!==stamp)throw new Error('Afterword changed');const result={pattern,panel,stamp};cardArtworkCache.set(s.id,result);return result}).catch(error=>{if(cardArtworkPromises.get(s.id)===task)cardArtworkPromises.delete(s.id);throw error});
 task.stamp=stamp;cardArtworkPromises.set(s.id,task);return task;
}

let annualCardViewer=null,pendingCardZoom=0,annualCardLightbox=null,annualViewerSequence=0;
function cardZoomSnapshot(){return annualCardViewer?.image?.isConnected&&document.body.classList.contains('card-preview-open')?annualCardViewer.zoom:0}
function validCardZoomState(s){return s.cardZoom===undefined||Number.isFinite(s.cardZoom)&&(s.cardZoom===0||s.cardZoom>=1&&s.cardZoom<=4)&&(!s.cardZoom||s.cardOpen===true&&s.annualConsent===true)}
function closeAnnualCardLightbox(notify=true){
 const box=annualCardLightbox;if(!box)return;annualCardLightbox=null;box.layer.remove();document.body.classList.remove('annual-lightbox-open');
 box.background.forEach(({node,inert})=>{node.inert=inert});box.focus?.focus?.();if(notify)box.onClose?.();
}
function showAnnualCardLightbox(src,onClose){
 closeAnnualCardLightbox(false);const layer=document.createElement('section');layer.className='annual-card-lightbox';layer.setAttribute('role','dialog');layer.setAttribute('aria-modal','true');layer.setAttribute('aria-label','年度卡大图');
 layer.innerHTML='<header class="annual-lightbox-header"><span>我的年度卡</span><button type="button" id="annualLightboxClose" aria-label="关闭大图">×</button></header><div class="annual-lightbox-scroll" id="annualLightboxScroll"><img id="annualLightboxImage" alt="完整年度卡，双击返回预览"></div>';
 const background=['#previewControls','#appPreviewStage','.shell','#appHost','#modalRoot'].map(selector=>document.querySelector(selector)).filter(Boolean).map(node=>({node,inert:!!node.inert}));
 annualCardLightbox={layer,onClose,background,focus:document.activeElement};background.forEach(({node})=>{node.inert=true});document.body.appendChild(layer);document.body.classList.add('annual-lightbox-open');
 const image=$('#annualLightboxImage'),scroll=$('#annualLightboxScroll'),close=$('#annualLightboxClose');image.src=src;image.draggable=false;scroll.scrollTop=0;scroll.scrollLeft=0;
 close.onclick=()=>closeAnnualCardLightbox();image.ondblclick=e=>{e.preventDefault();closeAnnualCardLightbox()};
 let touch=null,lastTap=null;image.onpointerdown=e=>{if(e.pointerType==='touch'&&e.isPrimary!==false)touch={id:e.pointerId,x:e.clientX,y:e.clientY,moved:false}};
 image.onpointermove=e=>{if(touch&&touch.id===e.pointerId&&Math.hypot(e.clientX-touch.x,e.clientY-touch.y)>12)touch.moved=true};
 image.onpointercancel=()=>{touch=null;lastTap=null};image.onpointerup=e=>{const t=touch;touch=null;if(!t||t.moved||t.id!==e.pointerId)return;const now=e.timeStamp||0;if(lastTap&&now-lastTap.time>0&&now-lastTap.time<320&&Math.hypot(e.clientX-lastTap.x,e.clientY-lastTap.y)<28){e.preventDefault();lastTap=null;closeAnnualCardLightbox()}else lastTap={time:now,x:e.clientX,y:e.clientY}};
 close.focus();
}
function resetAnnualCardViewer(){
 const view=annualCardViewer;if(view){view.request++;if(view.remote&&view.zoom)window.parent.postMessage({type:'lingocloud-annual:lightbox-dismiss',id:view.id},'*');annualCardViewer=null}closeAnnualCardLightbox(false);
}
function setAnnualCardZoom(value){
 const v=annualCardViewer;if(!v||!v.image.isConnected||!v.image.complete||!v.image.naturalWidth||annualImageCache.get(annualCardKey())?.url!==v.image.src||v.root.getAttribute('aria-busy')==='true')return false;
 const open=value>0;v.zoom=open?1:0;v.request++;const request=v.request;
 v.image.setAttribute('aria-expanded',String(open));notifyPreviewState();
 if(!open){if(v.remote)window.parent.postMessage({type:'lingocloud-annual:lightbox-dismiss',id:v.id},'*');else closeAnnualCardLightbox(false);v.image.focus();return true}
 if(v.remote){const entry=annualImageCache.get(annualCardKey());blobDataUrl(entry.blob).then(src=>{if(annualCardViewer!==v||v.request!==request||!v.zoom)return;window.parent.postMessage({type:'lingocloud-annual:lightbox-open',id:v.id,src},'*')}).catch(()=>{if(annualCardViewer===v&&v.request===request)setAnnualCardZoom(0)})}
 else showAnnualCardLightbox(v.image.src,()=>setAnnualCardZoom(0));
 return true;
}
function toggleAnnualCardZoom(){return setAnnualCardZoom(annualCardViewer?.zoom?0:1)}
function annualCardViewerReady(){
 const v=annualCardViewer;if(!v||!v.image.complete||!v.image.naturalWidth||v.root.getAttribute('aria-busy')==='true')return;
 if(pendingCardZoom){pendingCardZoom=0;setAnnualCardZoom(1)}
}
function bindAnnualCardViewer(){
 const image=$('#annualCardImage'),root=$('#cardPreviewBody');if(!image||!root)return;
 if(annualCardViewer?.image===image){annualCardViewerReady();return}
 resetAnnualCardViewer();const view={image,root,zoom:0,request:0,id:++annualViewerSequence,remote:!!APP_PREVIEW_PLATFORM&&window.parent!==window,lastTap:null,touch:null,ignoreDblClickUntil:0};annualCardViewer=view;
 image.tabIndex=0;image.draggable=false;image.setAttribute('role','button');image.setAttribute('aria-expanded','false');image.setAttribute('aria-label','年度卡缩略图，双击或按Enter在全窗口查看');
 image.ondblclick=e=>{if((e.timeStamp||0)<view.ignoreDblClickUntil)return;e.preventDefault();e.stopPropagation?.();toggleAnnualCardZoom()};
 image.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggleAnnualCardZoom()}};
 image.onpointerdown=e=>{if(e.pointerType!=='touch')return;if(e.isPrimary===false){view.touch=null;view.lastTap=null;return}view.touch={id:e.pointerId,x:e.clientX,y:e.clientY,moved:false}};
 image.onpointermove=e=>{const t=view.touch;if(t&&t.id===e.pointerId&&Math.hypot(e.clientX-t.x,e.clientY-t.y)>12)t.moved=true};
 image.onpointercancel=()=>{view.touch=null;view.lastTap=null};
 image.onpointerup=e=>{const t=view.touch;view.touch=null;if(e.pointerType!=='touch'||!t||t.id!==e.pointerId||t.moved)return;const now=e.timeStamp||0,previous=view.lastTap;if(previous&&now-previous.time>0&&now-previous.time<320&&Math.hypot(e.clientX-previous.x,e.clientY-previous.y)<28){e.preventDefault();view.lastTap=null;view.ignoreDblClickUntil=now+650;toggleAnnualCardZoom()}else view.lastTap={time:now,x:e.clientX,y:e.clientY}};
 annualCardViewerReady();
}
async function prepareAnnualPreview(key=annualCardKey()){
 resetAnnualCardViewer();await baseV19PrepareAnnualPreview(key);const image=$('#annualCardImage');if(!image?.isConnected||key!==annualCardKey())return;
 const onload=image.onload;image.onload=e=>{onload?.(e);bindAnnualCardViewer();annualCardViewerReady()};bindAnnualCardViewer();annualCardViewerReady();
}
function closeModal(){resetAnnualCardViewer();pendingCardZoom=0;return baseV19CloseModal()}
function handleCardViewerKeydown(e){
 if(annualCardLightbox&&(e.key==='Escape'||e.key==='Tab')){e.preventDefault();e.stopImmediatePropagation?.();if(e.key==='Escape')closeAnnualCardLightbox();else $('#annualLightboxClose').focus();return true}
 if(e.key==='Escape'&&annualCardViewer?.zoom&&annualCardViewer.image.isConnected){e.preventDefault();e.stopImmediatePropagation?.();setAnnualCardZoom(0);return true}return false;
}
document.addEventListener('keydown',handleCardViewerKeydown,true);
window.addEventListener('message',e=>{
 const m=e.data;if(APP_PREVIEW_PLATFORM){if(e.source===window.parent&&m?.type==='lingocloud-annual:lightbox-closed'&&m.id===annualCardViewer?.id)setAnnualCardZoom(0);return}
 const frame=$('#appPreviewFrame');if(e.source!==frame?.contentWindow||previewMode!=='app')return;
 if(m?.type==='lingocloud-annual:lightbox-open'&&previewState?.annualConsent&&previewState.cardOpen&&previewState.cardZoom>0&&Number.isSafeInteger(m.id)&&m.id>0&&typeof m.src==='string'&&m.src.length<24000000&&/^data:image\/png;base64,[A-Za-z0-9+/=]+$/.test(m.src)){
  showAnnualCardLightbox(m.src,()=>frame.contentWindow?.postMessage({type:'lingocloud-annual:lightbox-closed',id:m.id},'*'));annualCardLightbox.remoteId=m.id;
 }
 if(m?.type==='lingocloud-annual:lightbox-dismiss'&&m.id===annualCardLightbox?.remoteId)closeAnnualCardLightbox(false);
 if(m?.type==='lingocloud-annual:state'&&validPreviewState(m.state)&&(!m.state.cardOpen||!m.state.cardZoom))closeAnnualCardLightbox(false);
});


